const plant = flow.get('plant');
if (!plant || !/^[A-Za-z0-9_-]{1,40}$/.test(plant)) {
    node.status({ fill: 'red', shape: 'ring', text: 'pick a plant first' });
    return [ null, { payload: '(!) pick a plant first' } ];
}
const rid = 'r-' + Date.now().toString(36) + '-' + Math.floor(Math.random()*1e6).toString(36);
msg.topic = 'monitor-air/staging-01/reflect/cmd';
msg.payload = { request_id: rid, plant: plant, action: 'measure' };
msg.qos = 0;
msg.retain = false;
node.status({ fill: 'green', shape: 'dot', text: plant + ' ' + rid });
return [ msg, null ];

const plant = (msg.payload && msg.payload.plant) || (msg.req && msg.req.query && msg.req.query.plant) || '';
if (!/^[A-Za-z0-9_-]{1,40}$/.test(plant)) {
    msg.statusCode = 400;
    msg.payload = { error: 'plant required: ?plant=<id> or JSON body, [A-Za-z0-9_-] 1-40 chars' };
    return [ null, msg ];
}
const rid = 'r-' + Date.now().toString(36) + '-' + Math.floor(Math.random()*1e6).toString(36);
const cmd = { topic: 'monitor-air/staging-01/reflect/cmd', payload: { request_id: rid, plant: plant, action: 'measure' }, qos: 0, retain: false };
msg.payload = { status: 'accepted', request_id: rid, plant: plant };
msg.statusCode = 202;
return [ cmd, msg ];

const p = msg.payload || {};
msg.payload = (p.status || '?') + '  plant=' + (p.plant || '') + '  id=' + (p.request_id || '');
return msg;

// NFC weigh station — step 1: validate, ACK every copy, dedup (write-once).
const parts = (msg.topic || '').split('/');   // monitor-air/<dev>/measure/event_raw
const dev = parts[1];
const p = msg.payload || {};
const id = p.event_id, uid = p.uid, w = p.weight_g;
if (!dev || typeof id !== 'number' || typeof w !== 'number' || typeof uid !== 'string') {
    node.warn('bad event_raw on ' + msg.topic + ': ' + JSON.stringify(p));
    return [null, null];
}
// Ack first receipt AND retries (idempotent) so the ESP stops retrying ASAP.
const ack = { topic: 'monitor-air/' + dev + '/measure/ack', payload: { event_id: id }, qos: 0, retain: false };
// Dedup on (dev,event_id), ~60s TTL. event_id is session-scoped (resets on reboot);
// the short window makes cross-reboot repeats a non-issue.
const now = Date.now();
const seen = flow.get('seen') || {};
for (const k in seen) { if (now - seen[k] > 60000) delete seen[k]; }
const key = dev + ':' + id;
if (seen[key]) { flow.set('seen', seen); node.status({fill:'blue',shape:'ring',text:'dup ' + key}); return [ack, null]; }
seen[key] = now; flow.set('seen', seen);
// New event: carry it past the tag-map file read (which overwrites msg.payload).
msg.evt = { dev: dev, id: id, uid: uid, w: w };
node.status({fill:'grey',shape:'dot',text:'new ' + key});
return [ack, msg];

// NFC weigh station — step 2: msg.payload is tag-map.json contents (from the
// file-in node). Resolve uid -> plant_id. Missing file / bad JSON / unknown uid
// => 'unknown' but KEEP the raw uid so the record is never dropped / is back-fillable.
const e = msg.evt || {};
let plant_id = 'unknown';
try { const map = JSON.parse(msg.payload || '{}'); if (map[e.uid]) plant_id = map[e.uid]; }
catch (err) { node.warn('tag-map parse failed: ' + err.message); }
if (plant_id === 'unknown') node.warn('unknown tag uid ' + e.uid + ' on ' + e.dev);
msg.topic = 'monitor-air/' + e.dev + '/plant_weight';
msg.payload = { plant_id: plant_id, uid: e.uid, weight_g: e.w };
msg.qos = 0; msg.retain = false;
node.status({fill:'green',shape:'dot',text:plant_id + ' ' + e.w + 'g'});
return msg;
